mountPixelSimulator(document.querySelector<HTMLElement>('#pixel-simulator')!);
monet.apply();

const setSeed = (seed: string) => {
  monet.set({ seed });
  document.querySelectorAll<HTMLInputElement>('#custom-color,#color-picker,#dock-color').forEach((input) => input.value = seed);
  document.querySelectorAll<HTMLButtonElement>('.swatch,.dock-swatches button').forEach((button) => button.classList.toggle('active', button.dataset.seed?.toLowerCase() === seed.toLowerCase()));
};
document.querySelectorAll<HTMLButtonElement>('.swatch,.dock-swatches button').forEach((button) => button.addEventListener('click', () => setSeed(button.dataset.seed!)));
document.querySelectorAll<HTMLInputElement>('#color-picker,#dock-color').forEach((input) => input.addEventListener('input', () => setSeed(input.value)));
document.querySelector<HTMLInputElement>('#custom-color')!.addEventListener('change', (event) => { const value = (event.currentTarget as HTMLInputElement).value; if (/^#[\da-f]{6}$/i.test(value)) setSeed(value); });
document.querySelector<HTMLSelectElement>('#scheme-style')!.addEventListener('change', (event) => monet.set({ style: (event.currentTarget as HTMLSelectElement).value === 'tonal' ? 'tonal' : 'expressive' }));
document.querySelectorAll<HTMLButtonElement>('.theme-button,.dock-theme').forEach((button) => button.addEventListener('click', () => { monet.set({ dark: !monet.options.dark }); document.querySelectorAll('.theme-button .symbol,.dock-theme .symbol').forEach((item) => item.textContent = monet.options.dark ? 'light_mode' : 'dark_mode'); document.querySelectorAll<HTMLButtonElement>('.theme-button,.dock-theme').forEach((item) => item.setAttribute('aria-label', `Switch to ${monet.options.dark ? 'light' : 'dark'} theme`)); }));
document.querySelector<HTMLButtonElement>('.dock-mode')!.addEventListener('click', () => { const style: SchemeStyle = monet.options.style === 'expressive' ? 'tonal' : 'expressive'; monet.set({ style }); document.querySelector<HTMLButtonElement>('.dock-mode')!.title = style === 'tonal' ? 'Using Tonal Spot' : 'Using Expressive'; document.querySelector<HTMLSelectElement>('#scheme-style')!.value = style; });

let apkUrl = 'https://github.com/Velium-Chat/android/releases/latest';
document.querySelector<HTMLElement>('#download')!.addEventListener('click', () => window.open(apkUrl, '_blank', 'noopener,noreferrer'));
const release = fetch('https://api.github.com/repos/Velium-Chat/android/releases/latest', { headers: { Accept: 'application/vnd.github+json' } }).then((response) => { if (!response.ok) throw new Error('Release unavailable'); return response.json(); }).then((data: { tag_name?: string; assets?: Array<{ name: string; browser_download_url: string }> }) => {
  const asset = data.assets?.find((item) => item.name.toLowerCase().endsWith('.apk'));
  const button = document.querySelector<HTMLElement>('#download');
  if (data.tag_name) document.querySelector('#version-badge')!.textContent = data.tag_name;
  if (asset && button) { apkUrl = asset.browser_download_url; button.setAttribute('aria-label', `Download Velium ${data.tag_name ?? ''} APK`); }
}).catch(() => undefined);
void release;

document.querySelectorAll<HTMLButtonElement>('[data-haptic]').forEach((button) => button.addEventListener('click', () => {
  document.querySelectorAll('[data-haptic]').forEach((item) => item.classList.remove('selected')); button.classList.add('selected');
  document.querySelector('#haptic-name')!.textContent = button.dataset.haptic!;
  const wave = document.querySelector('#waveform')!; wave.classList.remove('playing'); void wave.clientWidth; wave.classList.add('playing');
}));
const range = document.querySelector<HTMLInputElement>('#type-scale')!;
range.addEventListener('input', () => { const value = Number(range.value); document.querySelector('#scale-output')!.textContent = `${value}%`; document.querySelector<HTMLElement>('#type-demo')!.style.setProperty('--demo-scale', String(value / 100)); });

const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add('in-view'); observer.unobserve(entry.target); } }), { threshold: .12 });
document.querySelectorAll('.feature-card,.safety-section,.repo-card,.section-heading').forEach((element) => observer.observe(element));
